def calculate_max_reward(n, s, r):
    """Calculates the maximum total reward in millions of VND for forming groups of three people whose ticket numbers sum to a target value.

    Args:
        n: The total number of tickets (numbered 1 to n).
        s: The target sum for each triplet (a, b, c with a < b < c).
        r: The reward per unique group.

    Returns:
        The maximum total reward rounded to the nearest integer.
    """
    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if i + j + k == s:
                    count += 1
    return round(count * r / 1000000)

def calculate_probability(type1_expired=5, type2_expired=3):
    """Calculates the probability that a chosen case is Type I given 2 expired cans out of 10.

    Args:
        type1_expired: Number of expired cans in a Type I case (default 5).
        type2_expired: Number of expired cans in a Type II case (default 3).

    Returns:
        The probability as a rounded float to two decimal places.
    """

    # Define probabilities for each case type
    prob_type1 = 2  # Twice the number of Type II cases
    prob_type2 = 1

    # Calculate probabilities of getting 2 expired cans from each case type
    prob_2_expired_type1 = (
        calculate_combination(type1_expired, 2) * calculate_combination(24 - type1_expired, 8)
    ) / (calculate_combination(24, 10))

    prob_2_expired_type2 = (
        calculate_combination(type2_expired, 2) * calculate_combination(24 - type2_expired, 8)
    ) / (calculate_combination(24, 10))

    # Calculate the overall probability using Bayes' Theorem
    prob_type1_given_2_expired = (
        (prob_type1 / (prob_type1 + prob_type2)) * prob_2_expired_type1
    ) / (
        ((prob_type1 / (prob_type1 + prob_type2)) * prob_2_expired_type1)
        + ((prob_type2 / (prob_type1 + prob_type2)) * prob_2_expired_type2)
    )

    return round(prob_type1_given_2_expired, 2)


def calculate_combination(n, k):
    """Calculates the number of combinations."""
    return factorial(n) // (factorial(k) * factorial(n - k))


def factorial(n):
    """Calculates the factorial of a number."""
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def calculate_max_profit(capacity, vat_rate, fixed_cost, production_cost_per_unit, max_order, price_coefficient):
    """Calculates the maximum monthly profit for Factory A.

    Args:
        capacity: The maximum production capacity of Factory A (in tons).
        vat_rate: The Value Added Tax rate (as a decimal).
        fixed_cost: The fixed cost of production (in million VND).
        production_cost_per_unit: The variable cost per unit produced (in million VND).
        max_order: The maximum order Factory B can place (in tons).
        price_coefficient: The coefficient in the selling price function (in million VND).

    Returns:
        The maximum monthly profit (after VAT) for Factory A (in million VND).
    """

    def calculate_profit(x):
      revenue = p(x)
      cost = C(x)
      return revenue - cost - vat_tax(revenue)

    def p(x):
      return 90 - 0.01 * x**2

    def C(x):
      return 0.5 * (200 + 27 * x)

    def vat_tax(revenue):
      return vat_rate * revenue

    max_profit = 0
    for x in range(1, min(capacity, max_order) + 1):
        profit = calculate_profit(x)
        if profit > max_profit:
            max_profit = profit

    return max_profit


