def calculate_inverse_prob(start, end):
    count = 0
    for num in range(start, end + 1):
        str_num = str(num)
        if int(str_num[0]) <= int(str_num[1]) + 1 <= int(str_num[2]) - 7 < int(str_num[3]) <= int(str_num[4]) + 2:
