def solve_production(raw_material_limit, working_hours_limit, type_i_raw_material, type_i_hours, type_i_profit, type_ii_raw_material, type_ii_hours, type_ii_profit):
    m = 0
    n = 0
    while raw_material_limit >= (type_i_raw_material * m) + (type_ii_raw_material * n):
        while working_hours_limit >= (type_i_hours * m) + (type_ii_hours * n):
            current_profit = (m * type_i_profit) + (n * type_ii_profit)
            # Check if this combination yields a higher profit than previous best
            if current_profit > (m_best * type_i_profit) + (n_best * type_ii_profit):
                m_best = m
                n_best = n
        m += 1
    return m_best + 2 * n_best

def solve_tic_tac_toe_problem(size, moves):
    """
    Calculates the number of winning sequences for An in a Tic-Tac-Toe game ending on the given move.

    Args:
        size (int): The size of the Tic-Tac-Toe grid (3x3).
        moves (int): The target number of moves for the game to end.

    Returns:
        int: The number of winning sequences.
    """
    if size != 3 or moves != 5:
        return 0  # Invalid input

    def is_winning(board):
        # Check rows, columns, and diagonals for a win
        for i in range(size):
            if board[i][0] == board[i][1] == board[i][2] and board[i][0] != ' ':
                return True
            if board[0][i] == board[1][i] == board[2][i] and board[0][i] != ' ':
                return True
        if (board[0][0] == board[1][1] == board[2][2] and board[0][0] != ' ') or \
           (board[0][2] == board[1][1] == board[2][0] and board[0][2] != ' '):
            return True
        return False

    winning_sequences = 0
    for i in range(3):  # An's first move possibilities
        for j in range(3):
            if board[i][j] == ' ':
                board[i][j] = 'X'
                for k in range(3):  # Binh's moves (4 possible)
                    for l in range(3):
                        if board[k][l] == ' ':
                            board[k][l] = 'O'
                            for m in range(3):  # An's winning move possibilities (5th move)
                                for n in range(3):
                                    if board[m][n] == ' ':
                                        board[m][n] = 'X'
                                        if is_winning(board):
                                            winning_sequences += 1
                                        board[m][n] = ' '  # Backtrack
                            board[k][l] = ' '  # Backtrack
                board[i][j] = ' '  # Backtrack

    return winning_sequences

def solve_grid_problem(rows, cols, red_squares):
    total_combinations = 2**(rows*cols)  # All squares can be either black or red

    valid_combinations = 0
    for i in range(rows):
        for j in range(cols):
            if (i > 0 and (j > 0 or j < cols - 1)) or (i < rows - 1 and (j > 0 or j < cols - 1)):
                continue  # Skip squares that are adjacent to others

    return valid_combinations / total_combinations

def count_ap_triplets(n, sum_limit):
    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            k = (i + j) // 2  # Calculate the middle term of the arithmetic progression
            if k <= sum_limit and i + j + k <= sum_limit:  # Check if the sum doesn't exceed the limit
                count += 1
    return count

