def count_rotor_arrangements(num_slots, masses):
    """
    Counts the number of ways to arrange blades on a rotor.

    Args:
        num_slots: The number of slots on the rotor (9).
        masses: A list of distinct integer masses for the blades (1 to 9).

    Returns:
        The number of valid arrangements.
    """

    def is_valid_arrangement(arrangement):
        """Checks if an arrangement satisfies the conditions."""
        for i in range(3):
            group = [arrangement[i * 3], arrangement[i * 3 + 1], arrangement[i * 3 + 2]]
            if sum(group) != sum(masses[:3]):  # Check if group masses are equal
                return False
        return True

    def generate_arrangements(index=0, current_arrangement=[]):
        """Generates all possible arrangements recursively."""
        if index == num_slots:
            if is_valid_arrangement(current_arrangement):
                yield current_arrangement
            return

        for mass in masses:
            if mass not in current_arrangement:
                new_arrangement = current_arrangement + [mass]
                yield from generate_arrangements(index + 1, new_arrangement)

    return len(list(generate_arrangements()))


