def solve_probability(n, k):
    total_combinations = (n choose 4)  # Calculate the total number of ways to choose 4 numbers from X

    favorable_combinations = 0  # Initialize count of favorable combinations

    for large_circle_num in range(1, n + 1):  # Iterate through all possible numbers for the large circle
        remaining_sum = large_circle_num * 3  # Sum required for small circles to exceed large circle
        for small_circle_1 in range(1, n + 1):
