                    if small_circle_2 != large_circle_num and small_circle_2 != small_circle_1:
                        small_circle_3 = remaining_sum - (small_circle_1 + small_circle_2)  # Calculate the third number
                        if small_circle_3 >= 1 and small_circle_3 <= n and small_circle_3 != large_circle_num:
                            favorable_combinations += 1

    probability = favorable_combinations / total_combinations  # Calculate probability
