def choose(n, r):
    """Calculates the number of combinations."""
    r = min(r, n - r)
    numer = 1
    denom = 1
    for i in range(r):
        numer *= (n - i)
        denom *= (i + 1)
    return numer // denom

def calculate_3430p(n):
    """Calculates the value of 3430 * p, where p is the probability that the sum of numbers in each column of a 3x3 grid is 0 given that the sum of numbers in each row is 0.

    Args:
        n: An integer used for testing purposes.

    Returns:
        The calculated value of 3430 * p rounded to two decimal places.
    """

    def is_valid_grid(grid):
        for row in grid:
            if sum(row) != 0:
                return False
        for col in range(3):
            if sum([grid[i][col] for i in range(3)]) != 0:
                return False
        return True

    count = 0
    total_grids = 27**9  # Each cell has 3 options (-1, 0, 1)

    for _ in range(total_grids):
        grid = [[random.choice([-1, 0, 1]) for _ in range(3)] for _ in range(3)]
        if is_valid_grid(grid):
            count += 1

    p = count / total_grids  # Probability of each column sum being 0
    return round(3430 * p, 2)

def solve_min_fine(N):
    total_fine = float('inf')
    for x in range(60, 301):
        t1 = 36 / (x + 10)
        t2 = 4 / (x - 30)
        n1 = int(N * t1)
        n2 = int(N * t2)
        fine_amount = n1 * x + n2 * (x - 20)
        total_fine = min(total_fine, fine_amount / 1000000)  # Convert to millions VND
    return round(total_fine)

def solve_max_profit(initial_price=30, initial_orders=60, initial_qty=100, price_step=2, order_dec=4, qty_dec=2, cost_price=24, max_price=50):
    max_profit = 0
    best_price = initial_price
    for price in range(initial_price, max_price + 1, price_step):
        orders = initial_orders - (price - initial_price) // price_step * order_dec
        qty = initial_qty - (price - initial_price) // price_step * qty_dec
        profit = (price - cost_price) * orders * qty
        if profit > max_profit:
            max_profit = profit
            best_price = price
    return round(best_price)

def solve_arithmetic_progression_prob(n, sum_limit):
    count = 0  
    for i in range(1, n - 2):
        for j in range(i + 1, n - 1):
            k = j + (j - i)  # Calculate the third number in the arithmetic progression
            if k <= sum_limit and i + j + k <= sum_limit:
                count += 1
    return (count * 6) // (n * (n - 1) * (n - 2))  

