import itertools

def calculate_loss_probability(hai_balls, son_balls, picks):
    """Calculates the probability that Son loses the game.

    Args:
        hai_balls: The number of balls Hai has.
        son_balls: The number of balls Son has.
        picks: The number of balls each person picks.

    Returns:
        The probability that Son loses, rounded to two decimal places.
    """

    def generate_numbers(balls):
      return [int(x) for x in itertools.permutations(range(1, balls + 1), picks)]

    hai_numbers = generate_numbers(hai_balls)
    son_numbers = generate_numbers(son_balls)

    loss_count = 0
    for hai_num in hai_numbers:
      for son_num in son_numbers:
        if int("".join(str(x) for x in sorted(hai_num, reverse=True))) > int("".join(str(x) for x in sorted(son_num, reverse=True))):
          loss_count += 1

    return round((len(hai_numbers) * len(son_numbers) - loss_count) / (len(hai_numbers) * len(son_numbers)), 2)
